This Terraform configuration creates an AWS S3 bucket to store your PDF file and uploads the local file at `assets/test.pdf` into that bucket as an S3 object. It also enables basic server-side encryption and blocks public access to the bucket.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the S3 bucket will be created."
  type        = string
  default     = "us-east-1"
}

variable "pdf_file_path" {
  description = "Local path to the PDF file to upload."
  type        = string
  default     = "assets/test.pdf"
}

